#!/usr/bin/env python3
"""Generate the static EclipseIQ website. No build/runtime dependencies."""
from pathlib import Path
from html import escape
import json,re
ROOT=Path(__file__).resolve().parents[1]
DATA=json.loads((ROOT/'scripts/content.json').read_text())
PAGES=DATA['pages'];OFFERINGS=DATA['offerings'];FAQ=DATA['faq']
BY_ID={x[0]:x for x in OFFERINGS}
def icon(name='arrow'):
 paths={'arrow':'M5 19 19 5M5 5h14v14','forward':'M4 12h16m-6-6 6 6-6 6','menu':'M3 6h18M3 12h18M3 18h18','plus':'M5 12h14M12 5v14'}
 return f'<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="{paths.get(name,paths["arrow"])}"/></svg>'
ARROW=icon()
def link(label,url,cls='text-link',external=False):
 return f'<a class="{cls}" href="{url}"'+(' target="_blank" rel="noopener noreferrer"' if external else '')+f'><span>{label}</span>'+('<span class="sr-only"> (opens in a new tab)</span>' if external else '')+ARROW+'</a>'
def build_page(key,body,alias=None):
 path,title,desc=PAGES[key];pre='./' if key in ['home','404'] else '../'
 if alias:path=alias;pre='../'
 def href(k):
  p=PAGES[k][0];return pre+(p+'index.html' if p.endswith('/') else p or 'index.html')
 canonical='https://eclipseiq.ca/'+(PAGES[key][0] if alias else path)
 brand=f'<img src="{pre}assets/eclipseiq-logo-original.png" width="202" height="88" alt="EclipseIQ Technologies Inc. — Smarter Insurance Solutions">'
 nav=''.join(f'<a href="{href(k)}"'+(' aria-current="page"' if k==key and not alias else '')+f'>{label}</a>' for k,label in [('services','Expertise'),('about','Company')])
 nav+=f'<a href="{href("home")}#eclipsesme">EclipseSME™</a><a href="{href("faq")}"'+(' aria-current="page"' if key=='faq' else '')+'>FAQ</a>'+link('Contact',href('contact'),'nav-contact')
 schema={'@context':'https://schema.org','@type':'Organization','name':'EclipseIQ Technologies Inc.','url':'https://eclipseiq.ca/','logo':'https://eclipseiq.ca/assets/eclipseiq-logo-original.png','description':PAGES['home'][2],'sameAs':['https://www.linkedin.com/company/eclipseiq']}
 html=f'''<!doctype html>
<html lang="en-CA"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)} | EclipseIQ Technologies Inc.</title><meta name="description" content="{escape(desc,quote=True)}"><meta name="theme-color" content="#071f2c"><meta name="referrer" content="strict-origin-when-cross-origin"><link rel="canonical" href="{canonical}">{'<meta name="robots" content="noindex">' if alias or key=='404' else ''}<meta property="og:type" content="website"><meta property="og:locale" content="en_CA"><meta property="og:site_name" content="EclipseIQ Technologies Inc."><meta property="og:title" content="{escape(title,quote=True)}"><meta property="og:description" content="{escape(desc,quote=True)}"><meta property="og:url" content="{canonical}"><meta property="og:image" content="https://eclipseiq.ca/assets/social.png"><meta property="og:image:alt" content="EclipseIQ — Insurance, connected."><meta name="twitter:card" content="summary_large_image"><link rel="icon" href="{pre}assets/eclipseiq-logo-original.png" type="image/png"><link rel="preload" href="{pre}assets/fonts/manrope.woff2" as="font" type="font/woff2" crossorigin><link rel="stylesheet" href="{pre}assets/styles.css"><script src="{pre}assets/config.js" defer></script><script src="{pre}assets/site.js" defer></script><script src="{pre}assets/consent.js" defer></script><script type="application/ld+json">{json.dumps(schema)}</script></head>
<body class="page-{key}"><a class="skip-link" href="#main">Skip to content</a><header class="header"><div class="container header-inner"><a class="brand" href="{href('home')}" aria-label="EclipseIQ Technologies Inc. home">{brand}</a><button class="menu-toggle" aria-expanded="false" aria-controls="navigation" hidden>Menu {icon('menu')}</button><nav id="navigation" aria-label="Main navigation">{nav}</nav></div></header><main id="main">{body.replace('@ROOT@',pre)}</main>
<footer class="footer"><div class="container"><div class="footer-invitation"><p class="eyebrow">A conversation is a good place to start.</p>{link('Let’s put the<br>pieces together.',href('contact'),'invitation-link')}</div><div class="footer-content"><div><a class="brand" href="{href('home')}">{brand}</a><p>Insurance technology.<br>Business perspective. Practical delivery.</p></div><div class="footer-nav"><p class="eyebrow">Explore</p><a href="{href('services')}">Services & capabilities</a><a href="{href('about')}">About EclipseIQ</a><a href="{href('home')}#eclipsesme">EclipseSME™</a><a href="{href('faq')}">Frequently asked questions</a></div><div class="footer-location"><p class="eyebrow">Canadian expertise.<br>International perspective.</p><p>Insurers. MGAs. Reinsurers.<br>Brokers. Specialty insurance.</p>{link('LinkedIn','https://www.linkedin.com/company/eclipseiq','footer-social',True)}</div></div><div class="footer-bottom"><p>© 2026 EclipseIQ Technologies Inc.</p><div><a href="{href('privacy')}">Cookies & privacy</a><button class="cookie-preferences" hidden>Cookie preferences</button></div></div></div></footer>
<section id="cookie-banner" class="cookie-banner" aria-labelledby="cookie-title" hidden><div><h2 id="cookie-title">Your privacy, your choice.</h2><p>Optional cookies help us understand website usage. Accept or reject them and change your choice at any time. <a href="{href('privacy')}">Cookies & privacy</a></p></div><div class="cookie-actions"><button class="button button-small" data-cookie-choice="accepted">Accept</button><button class="button button-outline button-small" data-cookie-choice="rejected">Reject</button></div></section></body></html>'''
 target=ROOT/('index.html' if key=='home' else path if key=='404' else path+'index.html');target.parent.mkdir(parents=True,exist_ok=True);target.write_text(html)

def explorer():
 pathways=[('modernize','Modernize the core.','Connect the systems.<br>Improve the operation.','Legacy technology, disconnected information and manual work rarely exist in isolation. Bring architecture, data and operational workflows into one practical modernization plan.',['transformation','assessment','audit','security'],['Understand the landscape','Connect systems & data','Improve operational workflows']),('lead','Lead the next phase.','Senior perspective.<br>Practical involvement.','Bring insurance and technology leadership into the decisions that matter. Align strategy, guide delivery and support the people who will make change work.',['leadership','coaching','consulting'],['Set direction','Guide the change','Support the team']),('engineer','Build what fits.','Industry understanding.<br>Engineering depth.','Turn specialized insurance requirements into software and connected systems. Work with existing platforms, custom integrations or EclipseSME—our own insurance platform.',['software','transformation'],['Understand requirements','Design & integrate','Implement with purpose'])]
 out='<section class="explorer-section" id="offerings-section"><div id="capabilities" class="anchor-target"></div><div class="container"><div class="section-intro"><p class="eyebrow">02 / From priorities to progress</p><h2>What needs<br>to move next?</h2></div><div class="explorer" data-explorer><div class="explorer-selector"><p class="selector-label">Choose a starting point</p><div class="pathway-tabs" role="tablist" aria-label="Your insurance technology priorities" aria-orientation="vertical" hidden>'
 for i,(slug,title,*_) in enumerate(pathways):out+=f'<button id="tab-{slug}" type="button" role="tab" aria-controls="panel-{slug}" aria-selected="{str(i==0).lower()}" tabindex="{0 if i==0 else -1}" data-pathway="{slug}"><span class="tab-number">0{i+1}</span><span>{title}</span>{icon("forward")}</button>'
 out+='</div><p class="explorer-note">A focused engagement or a wider transformation. Start with what your organization needs.</p></div><div class="explorer-panels">'
 for i,(slug,title,heading,desc,services,steps) in enumerate(pathways):
  out+=f'<section class="pathway-panel" id="panel-{slug}" aria-labelledby="heading-{slug}" data-pathway-panel="{slug}"><div class="panel-heading"><span class="panel-index">0{i+1}</span><div><p class="eyebrow" id="heading-{slug}">{title}</p><h3>{heading}</h3></div></div><p class="panel-copy">{desc}</p><ol class="pathway-sequence" aria-label="Approach">'+''.join(f'<li><span>0{j+1}</span>{step}</li>' for j,step in enumerate(steps))+'</ol><nav class="related-services" aria-label="Related services">'+''.join(link(BY_ID[s][1],f'@ROOT@services/index.html#{s}') for s in services)+'</nav></section>'
 out+='</div></div><div class="capability-index"><p class="eyebrow">The full capability index</p><nav aria-label="All services">'+''.join(f'<a href="@ROOT@services/index.html#{s}">{t}</a>' for s,t,*_ in OFFERINGS)+'</nav></div></div></section>'
 return out

def main():
 home='''<section class="masthead"><div class="container"><div class="masthead-top"><p class="eyebrow">EclipseIQ / Insurance technology</p><span class="masthead-descriptor">Perspective → Implementation</span></div><div class="masthead-composition"><h1>Insurance,<br><span>connected.</span></h1><div class="masthead-copy"><p class="masthead-statement">Technology decisions should work for the whole business.</p><p>Strategy, operational leadership and software engineering for insurers, MGAs, reinsurers and brokers.</p>'''+link('Explore our expertise','#offerings-section','button button-light')+'''</div></div><div class="masthead-foot"><span>Consulting. Leadership. Software.</span><a href="#perspective">Discover the EclipseIQ perspective <span aria-hidden="true">↓</span></a></div></div></section>
<section class="thesis-section" id="perspective"><div class="container thesis-grid"><p class="eyebrow">01 / The company</p><div><h2>A technology partner<br>that understands<br><span>the insurance business.</span></h2><div class="thesis-copy"><p>Insurance runs on connected decisions: underwriting, policy operations, data, people and systems. We work across those connections.</p><p>EclipseIQ Technologies combines executive leadership and hands-on insurance technology experience. From Canada to international organizations, we help turn business priorities into practical change.</p>'''+link('Get to know EclipseIQ','./about/index.html')+'''</div></div></div></section>'''+explorer()+'''
<section class="software-feature" id="eclipsesme"><div class="container"><div class="software-topline"><p class="eyebrow">03 / Software, by EclipseIQ</p><span>OUR INSURANCE PLATFORM</span></div><div class="software-heading"><h2>EclipseSME<span>™</span></h2><p>Insurance knowledge,<br>working in software.</p></div><div class="software-content"><p>Developed by EclipseIQ, EclipseSME supports specialty insurers, MGAs and program administrators with configurable underwriting, policy administration and operational workflows.</p><div><p>Our corporate expertise extends beyond a single platform. EclipseSME is one way we put that expertise into practice.</p>'''+link('Explore EclipseSME','https://eclipsesme.com/','button',True)+link('Arrange a demonstration','./contact/index.html?interest=demo')+'''</div></div><ol class="policy-lifecycle" aria-label="EclipseSME policy lifecycle capabilities"><li><span>01</span>Quote & underwrite</li><li><span>02</span>Issue & administer</li><li><span>03</span>Endorse & renew</li><li><span>04</span>Connect & report</li></ol></div></section>'''
 build_page('home',home)
 # Services are organized by type of engagement, preserving every verified offering.
 services='''<section class="expertise-masthead"><div class="container"><p class="eyebrow">Expertise / Services & capabilities</p><h1>A sharper view.<br>A practical path.</h1><div class="expertise-lead"><p>Insurance knowledge. Senior leadership.<br>The engineering to make it work.</p><p>Work with us on a focused priority or across a wider transformation. The business need shapes the engagement.</p></div></div></section><section class="practice-document"><div class="container practice-layout"><aside class="practice-index"><p class="eyebrow">Our practice</p><nav aria-label="Practice areas"><a href="#advisory"><span>01</span> Advisory & assurance</a><a href="#executive"><span>02</span> Leadership & people</a><a href="#engineering"><span>03</span> Software & systems</a></nav>'''+link('Discuss your priorities','@ROOT@contact/index.html')+'''</aside><div class="practice-chapters">'''
 groups=[('advisory','01','Advise with perspective.','See the whole environment. Make decisions with the operational and technology context in view.',['consulting','assessment','audit','security']),('executive','02','Lead with experience.','Bring executive guidance and team development into the work of business transformation.',['leadership','coaching']),('engineering','03','Engineer with purpose.','Connect insurance requirements to architecture, integrations, data and working software.',['transformation','software'])]
 for group,num,title,desc,slugs in groups:
  services+=f'<section class="practice-chapter" id="{group}"><p class="eyebrow">{num} / Practice area</p><h2>{title}</h2><p class="chapter-intro">{desc}</p><div class="service-disclosures">'
  for s in slugs:
   slug,label,lead,body,items,_=BY_ID[s]
   interest={'software':'demo','transformation':'modernization'}.get(slug,slug)
   services+=f'<details class="service-entry" id="{slug}"><summary>{label}{icon("plus")}</summary><div><h3>{lead}</h3><p>{body}</p><ul>'+''.join(f'<li>{x}</li>' for x in items)+'</ul>'+link('Discuss this service',f'@ROOT@contact/index.html?interest={interest}')+'</div></details>'
  services+='</div></section>'
 services+='</div></div></section><section class="engagement-note"><div class="container"><p class="eyebrow">The engagement</p><h2>Understand first.<br>Make the next step useful.</h2><p>Start with the business objectives, operational challenges and systems already in place. From there, define the scope, priorities and implementation approach together.</p></div></section>'
 build_page('services',services)
 about='''<section class="company-masthead"><div class="container"><p class="eyebrow">Company / EclipseIQ Technologies Inc.</p><h1>Insurance is<br>the context.<br><span>Engineering<br>is the craft.</span></h1><div class="company-masthead-note"><span>CANADA / INTERNATIONAL</span><p>Executive perspective.<br>Operational understanding.<br>Hands-on technology delivery.</p></div></div></section><section class="company-narrative"><div class="container document-grid"><div><p class="eyebrow">An industry perspective</p><h2>The business<br>behind the system.</h2></div><div class="prose"><p class="lead">We work where insurance operations and technology meet.</p><p>EclipseIQ Technologies Inc. draws on decades of executive leadership and hands-on experience in insurance technology, operations and digital transformation.</p><p>We help insurers, MGAs, reinsurers, brokers, program administrators and specialty insurance organizations modernize systems and improve how work gets done.</p><p>Based in Canada, we work with organizations here and internationally. Our engagements can involve strategic advice, technology leadership, custom software, third-party platforms or our own EclipseSME™ platform.</p></div></div></section><section class="leadership-section"><div class="container"><div class="leadership-intro"><p class="eyebrow">Senior leadership / Practical involvement</p><h2>Direction, operations<br>and delivery.<br><span>In the same conversation.</span></h2></div><div class="leadership-roles"><article><h3>CIO<span>01</span></h3><p>Technology strategy.<br>Governance. Investment priorities.</p></article><article><h3>COO<span>02</span></h3><p>Operational perspective.<br>Business alignment. Change.</p></article><article><h3>CTO<span>03</span></h3><p>Architecture. Engineering.<br>Technology delivery.</p></article></div><p class="leadership-note">Fractional CIO / COO / CTO engagements bring experienced guidance into transitions and complex initiatives without a full-time executive appointment.</p></div></section><section class="expertise-register"><div class="container document-grid"><div><p class="eyebrow">What we understand</p><h2>Insurance depth.<br>Technical range.</h2></div><dl><div><dt>Insurance operations</dt><dd>Underwriting, policy administration, claims workflows and the people doing the work.</dd></div><div><dt>Architecture & modernization</dt><dd>Legacy systems, solution design, integration and third-party implementation.</dd></div><div><dt>Data & analytics</dt><dd>Data quality, conversion, migration, reporting and information across systems.</dd></div><div><dt>Specialty insurance & reinsurance</dt><dd>The operating context of insurers, MGAs, reinsurers, brokers and program administrators.</dd></div><div><dt>Readiness & risk</dt><dd>Governance, audit preparation, security review, coaching and operational performance.</dd></div></dl></div></section>'''
 build_page('about',about)
 faq='''<section class="reference-masthead"><div class="container"><p class="eyebrow">Reference / Frequently asked questions</p><h1>Good questions.<br>Clear answers.</h1></div></section><section class="reference-section"><div class="container reference-layout"><aside><p class="reference-count">14<span>questions, answered.</span></p><div class="faq-search" hidden><label for="faq-search">Find a topic</label><input id="faq-search" type="search" placeholder="Try “migration”" aria-controls="faq-answers"><p id="faq-count" role="status" aria-live="polite">14 questions</p></div>'''+link('Ask us something else','@ROOT@contact/index.html')+'''</aside><div class="faq-list" id="faq-answers">'''+''.join(f'<details><summary>{q}{icon("plus")}</summary><div><p>{a}</p></div></details>' for q,a in FAQ)+'''<p id="faq-empty" hidden>No matching questions. Try a different word or contact us.</p></div></div></section>'''
 build_page('faq',faq)
 form=(ROOT/'scripts/partials/contact-form.tpl').read_text()
 contact='''<section class="contact-studio"><div class="container"><div class="contact-title"><p class="eyebrow">Contact / Start a conversation</p><h1>Let’s talk.</h1></div><div class="contact-layout"><aside><h2>What’s next<br>for your business?</h2><p>Tell us about your organization and the priority you want to move forward.</p><p>Consulting, systems modernization, fractional leadership or an EclipseSME demonstration—a high-level overview is enough to begin.</p><div class="contact-locale"><p class="eyebrow">Where we work</p><p>Based in Canada.<br>Working internationally.</p></div><p class="contact-discretion">Please leave confidential, financial and policyholder information out of your initial inquiry.</p></aside><div class="contact-form-wrap">'''+form+'''</div></div></div></section>'''
 build_page('contact',contact)
 legal=(ROOT/'scripts/partials/privacy-body.tpl').read_text()
 toc=[]
 def heading(m):
  attrs,title=m.groups();slug='cookies' if 'id="cookies"' in attrs else re.sub('[^a-z0-9]+','-',title.lower()).strip('-');toc.append((slug,title));return f'<h2 id="{slug}">{title}</h2>'
 legal=re.sub(r'<h2([^>]*)>(.*?)</h2>',heading,legal)
 privacy='''<section class="document-masthead"><div class="container"><p class="eyebrow">Website information</p><h1>Cookies<br>& privacy.</h1></div></section><section class="legal-section"><div class="container legal-layout"><aside><p class="eyebrow">Contents</p><nav aria-label="Privacy notice contents">'''+''.join(f'<a href="#{slug}">{label}</a>' for slug,label in toc)+'''</nav></aside><div class="legal">'''+legal+'</div></div></section>'
 build_page('privacy',privacy)
 for alias in ['privacy/','cookie-policy-ca/','cookie-policy-ca-2/']:build_page('privacy',privacy,alias)
 build_page('404','<section class="error-page"><div class="container"><p class="eyebrow">404 / Page not found</p><h1>Let’s reconnect.</h1><p>This page may have moved. Find your way back to EclipseIQ.</p>'+link('Return to the homepage','./index.html','button')+'</div></section>')
 (ROOT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n'+''.join(f'  <url><loc>https://eclipseiq.ca/{path}</loc></url>\n' for k,(path,_,_) in PAGES.items() if k!='404')+'</urlset>\n')
 (ROOT/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: https://eclipseiq.ca/sitemap.xml\n')
 print('Generated 10 pages with the new editorial design system')
if __name__=='__main__':main()
